{{velocity}} #mesureBureaux ($bureaux) ## Filters come from the location (KTD6): the space Mesures.<code>.<Secteur|Synthese> of each sheet. #set ($bureau = "$!request.bureau") #if (!$bureaux.containsKey($bureau)) #set ($bureau = '') #end #set ($perimetre = "$!request.perimetre") #if (!$mesurePerimetres.containsKey($perimetre)) #set ($perimetre = '') #end #if ($bureau != '') #set ($spaceFilter = "Mesures.${bureau}.$!perimetre") #elseif ($perimetre != '') #set ($spaceFilter = ".$perimetre") #else #set ($spaceFilter = 'Mesures.') #end Une fiche par mesure : son historique, sa documentation et la provenance de ses données. La liste ne montre que les fiches que vous pouvez lire.
[[Nouvelle fiche>>Mesures.NouvelleMesure||class="btn btn-primary"]]
{{html}} <form method="get" action="$doc.getURL('view')" class="form-inline"> <label for="bureau">Bureau</label> <select id="bureau" name="bureau"><option value="">Tous</option> #foreach ($code in $bureaux.keySet()) <option value="$escapetool.xml($code)"#if ($code == $bureau) selected="selected"#end>$escapetool.xml($code) – $escapetool.xml($bureaux.get($code).name)</option> #end </select> <label for="perimetre">Périmètre</label> <select id="perimetre" name="perimetre"><option value="">Tous</option> #foreach ($key in $mesurePerimetres.keySet()) <option value="$key"#if ($key == $perimetre) selected="selected"#end>$escapetool.xml($mesurePerimetres.get($key))</option> #end </select> <button type="submit" class="btn btn-default">Filtrer</button> </form> {{/html}}
{{liveData id="mesures" properties="doc.title,doc.space,vecteurJuridique,dateCreation,doc.date,doc.author" source="liveTable" sourceParameters="className=Mesures.Code.MesureClass" filters="doc.space=$escapetool.url($spaceFilter)" sort="doc.date:desc" limit="25" }} { "meta": { "propertyDescriptors": [ {"id": "doc.title", "name": "Intitulé"}, {"id": "doc.space", "name": "Emplacement (Mesures.bureau.périmètre)"}, {"id": "doc.date", "name": "Dernière modification"}, {"id": "doc.author", "name": "Modifiée par"} ] } } {{/liveData}}
